def create_writer(
    format: str, output_path: str, **kwargs: Any
) -> BaseWriter:
    """Factory function to create the appropriate writer."""
    writers = {
        "json": JsonWriter,
        "csv": CsvWriter,
        "null": NullWriter,
    }
    cls = writers.get(format)
    if cls is None:
        raise ValueError(f"Unknown writer format: {format}. Available: {list(writers.keys())}")
    return cls(output_path, **kwargs)  # type: ignore


def write_records(
    records: list[Any], output_path: str, format: str = "json", **kwargs: Any
) -> BatchResult:
    """Convenience function to write a list of records to a file."""
    result = BatchResult()
    start = time.time()
    writer = create_writer(format, output_path, **kwargs)
    try:
        for record in records:
            try:
                writer.write_record(record)
            except Exception as e:
                result.add_failure(str(e))
        writer.flush()
    finally:
        writer.close()
    result.duration_ms = (time.time() - start) * 1000
    return result


def write_batch(
    records: Iterator[Any], output_path: str, format: str = "json", **kwargs: Any
) -> BatchResult:
    """Convenience function to write records from an iterator."""
    result = BatchResult()
    start = time.time()
    writer = create_writer(format, output_path, **kwargs)
    try:
        for record in records:
            try:
                writer.write_record(record)
            except Exception as e:
                result.add_failure(str(e))
        writer.flush()
    finally:
        writer.close()
    result.duration_ms = (time.time() - start) * 1000
    return result
